const $ = (id) => document.getElementById(id);
const $$ = (query,root=document) => [...root.querySelectorAll(query)];
const esc = (value) => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#7ae0c0','#b49bfa','#88c6e9','#f2c283','#ee9bba','#88cfa2'];
const state={server:null,session:null,sessionId:null,sessions:[],labels:[],settings:{},annotations:[],events:[],history:[],samples:{},live:true,paused:false,end:10,window:10,hidden:new Set(),selectedLabel:null,selection:null,drag:null,paired:false,processed:null,view:'viewer',lastSessionRefresh:0,polling:false,fetching:false,revision:null,model:null,scanned:[],lastError:'',hover:null};
const formatTime=(t,ms=false)=>{t=Math.max(0,Number(t)||0);const m=Math.floor(t/60),s=Math.floor(t%60);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}${ms?'.'+String(Math.floor(t%1*1000)).padStart(3,'0'):''}`};
const durationLabel=t=>Number(t)<60?`${Number(t||0).toFixed(1)} s`:`${(Number(t||0)/60).toFixed(1)} min`;
const dateLabel=t=>t?new Date(typeof t==='number'?t*1000:t).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Unknown date';
const nativeUnits=()=>state.session?.units||state.server?.hardware?.units||'counts';
const sessionDuration=()=>Math.max(0,Number(state.session?.duration||(state.server?.recording?.armed?state.server?.latest_t:0)||0));
const latestLive=()=>Math.max(0,...Object.values(state.server?.live?.channels||{}).map(rows=>rows.at(-1)?.t||0));
const visibleRange=()=>({start:Math.max(0,state.end-state.window),end:Math.max(state.window,state.end)});
const activeChannels=()=>Object.keys(state.samples).filter(ch=>!state.hidden.has(ch));
function toast(message,kind='success'){const el=document.createElement('div');el.className=`toast ${kind}`;el.textContent=message;$('toast-stack').append(el);setTimeout(()=>el.remove(),kind==='error'?9000:4200)}
async function api(path,body){const response=await fetch(path,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok||result?.error)throw new Error(result.error||`Request failed (${response.status})`);return result}
async function action(name,payload={},notify){try{const result=await api('/api/action',{action:name,...payload});if(notify)toast(notify);return result}catch(error){toast(error.message,'error');error.reported=true;throw error}}
function bind(id,fn){$(id)?.addEventListener('click',async e=>{try{await fn(e)}catch(error){if(!error.reported)toast(error.message||String(error),'error');console.error(error)}})}
function fillSelect(id,options,selected){const el=$(id),previous=selected??el.value;el.innerHTML=options;const match=[...el.options].find(o=>o.value===String(previous));if(match)el.value=previous}
function selectedSessionIds(){return [...$('analysis-sessions').selectedOptions].map(o=>o.value).filter(Boolean)}
function labelOptionHtml(includeUnnamed=true){return `${includeUnnamed?'<option value="">Unnamed / all conditions</option>':''}${state.labels.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('')}`}
function openModal(title,body,buttons=[]){$('modal-content').innerHTML=`<div class="modal-heading"><h2>${esc(title)}</h2><button class="icon-button modal-close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div><div class="modal-actions">${buttons.map((b,i)=>`<button class="button ${b.primary?'primary':''} ${b.danger?'danger':''}" data-modal-button="${i}">${esc(b.text)}</button>`).join('')}</div>`;$('modal-content').querySelector('.modal-close').onclick=()=>closeModal();buttons.forEach((b,i)=>{$('modal-content').querySelector(`[data-modal-button="${i}"]`).onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{await b.action();}catch(error){if(!error.reported)toast(error.message||String(error),'error');console.error(error)}finally{if(button.isConnected)button.disabled=false}}});if(!$('modal').open)$('modal').showModal()}
function closeModal(){$('modal').close()}
function showView(view){state.view=view;$$('.view').forEach(v=>v.classList.toggle('active-view',v.id===`view-${view}`));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('page-breadcrumb').textContent=$(`view-${view}`).querySelector('h1').textContent;if(['library','analysis','compare','processing','experiments'].includes(view))refreshLibrary();if(view==='viewer')requestAnimationFrame(drawAll);if(view==='sync')renderSync();}
$$('[data-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.view)));
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);e.preventDefault()});

async function poll(){if(state.polling)return;state.polling=true;try{const result=await api('/api/state');state.server=result;state.labels=result.labels||state.labels;state.settings=result.settings||state.settings;state.selectedLabel=result.selected_label??null;const armed=result.recording?.armed;if(armed&&result.active_session){if(state.sessionId!==result.active_session.id&&state.live){state.sessionId=result.active_session.id;state.annotations=[];state.revision=null}if(state.sessionId===result.active_session.id)state.session=result.active_session;}if(state.live&&!state.paused){state.samples=result.live?.channels||{};state.end=Math.max(state.window,armed?Number(result.latest_t||0):latestLive());}if(state.sessionId&&Date.now()-state.lastSessionRefresh>1800){await refreshSession(false)}renderLiveState();renderLabels();renderProtocol();if(state.view==='sync')renderSync();if(state.live&&!state.paused)drawAll();const error=result.errors?.at(-1);if(error&&error!==state.lastError){state.lastError=error;toast(error,'error')}}catch(error){$('local-status').innerHTML='<i style="background:var(--red)"></i> Service unavailable';$('hardware-summary').textContent='Local service unavailable';if(state.lastError!==error.message){state.lastError=error.message;toast('Cannot reach the local EEG service. '+error.message,'error')}}finally{state.polling=false}}
async function refreshSession(force=true){if(!state.sessionId)return;const id=state.sessionId;const result=await api(`/api/session?id=${encodeURIComponent(id)}`);if(id!==state.sessionId)return;state.lastSessionRefresh=Date.now();state.session=result.session;state.annotations=(result.annotations||[]).sort((a,b)=>a.start-b.start);state.events=result.events||[];state.history=result.history||[];state.results=result.results||[];state.revision=result.session.revision;renderAnnotations();if(force)drawAll();}
async function loadSamples(){if(!state.sessionId||state.fetching)return;state.fetching=true;try{const id=state.sessionId,{start,end}=visibleRange();const rows=await api(`/api/samples?id=${encodeURIComponent(id)}&start=${start}&end=${end}&limit=14000`);if(id!==state.sessionId)return;state.samples=Object.groupBy?Object.groupBy(rows,r=>r.channel):rows.reduce((a,r)=>((a[r.channel]??=[]).push(r),a),{});renderChannels();drawAll()}finally{state.fetching=false}}
async function openSession(id){state.sessionId=id;state.live=false;state.paused=true;state.selection=null;state.processed=null;await action('open',{session_id:id});await refreshSession();const savedAnalysis=state.results?.find(r=>r.kind==='analysis'&&r.data?.channels?.length)?.data;state.processed=savedAnalysis||null;$('processed-name').textContent=savedAnalysis?.pipeline?.name||'No pipeline selected';$('processed-note').textContent=savedAnalysis?`Saved ${savedAnalysis.pipeline?.mode||'offline'} pipeline · ${formatTime(savedAnalysis.start,true)} — ${formatTime(savedAnalysis.end,true)} · results restored from this session.`:'Select a saved pipeline and run processing to compare aligned results.';state.end=Math.max(state.window,(savedAnalysis?.start||0)+state.window);await loadSamples();renderLiveState();showView('viewer');}
function renderLiveState(){const server=state.server||{},hw=server.hardware||{},rec=server.recording||{};const hardwareState=hw.state||hw.status||(hw.streaming?'streaming':hw.connected?'connected':'disconnected');const source=state.live?(hw.source||hw.mode||'unknown'):(state.session?.source||'replay');const simulated=/simulat/i.test(source);const isStreaming=Object.values(hw.samples_arriving||{}).some(Boolean);$('hardware-summary').textContent=hw.error?'Connection error':isStreaming?'Zone · streaming':hw.connected?'Zone · connected, awaiting data':'Device disconnected';$('hardware-dot').style.background=isStreaming?'var(--teal)':hw.connected?'var(--warning)':'var(--dim)';$('footer-stream-dot').style.background=isStreaming?'var(--teal)':'var(--dim)';$('footer-stream').textContent=isStreaming?(simulated?'Receiving simulated samples':'Receiving real device samples'):hw.streaming?'Stream requested · waiting for samples':hw.connected?'Connected · no recent samples':'Disconnected';$('source-badge').textContent=simulated?(state.live?'SIMULATED DATA':'SIMULATED REPLAY'):!state.live?'RECORDED SESSION':isStreaming?'LIVE DEVICE':'NO SOURCE';$('source-badge').className=`mode-badge ${simulated?'simulated':isStreaming?'real':''}`;$('stream-state').textContent=state.paused?'Viewer paused':state.live?(isStreaming?'Streaming':'Awaiting samples'):'Playback';$('stream-state').className=`inline-status ${isStreaming&&!state.paused?'streaming':''}`;$('record-toggle').classList.toggle('recording',!!rec.armed);$('record-toggle').disabled=!rec.armed&&!hw.connected;$('record-toggle').title=!rec.armed&&!hw.connected?'Connect earbuds or start a simulated stream before recording':'';$('record-toggle').innerHTML=`<span class="record-circle"></span> ${rec.armed?'Stop recording':'Start recording'}`;$('recording-dot').style.background=rec.armed?'var(--red)':'var(--dim)';$('recording-status').textContent=rec.error?'Recording failed':rec.armed?(server.latest_t>0?'Recording':'Recording armed'):state.session?state.session.title:'Ready to explore';const section=server.section,countdown=server.countdown;let hint=state.sessionId&&!state.live?'Reviewing saved samples':isStreaming?'Every received sample is preserved when recording.':'Connect your earbuds or start a simulated stream.';if(rec.armed)hint=section?`Labeling: ${section.label} · ${formatTime(Math.max(0,(server.latest_t||0)-section.start))}`:countdown?`Section begins in ${Math.ceil(countdown.remaining)}…`:'No active label · all received samples are being saved';if(state.paused&&rec.armed)hint+=' · viewer paused';$('annotation-live-status').textContent=hint;$('session-clock').textContent=formatTime(rec.armed?server.latest_t:sessionDuration(),true);$('section-button-text').textContent=countdown?'Cancel countdown':section?'End section':'Start section';$('section-toggle').style.background=section?'#b6eedb':'';$('viewer-pause').textContent=state.paused?'▶':'Ⅱ';$('viewer-pause').ariaLabel=state.paused?'Resume viewer or playback':'Pause viewer';$('return-live').textContent=state.live&&!state.paused?'● Live':'↗ Return to live';$('return-live').classList.toggle('paused',!state.live||state.paused);$('previous-seconds-label').textContent=state.settings.previous_seconds||10;$('footer-samples').textContent=`${Number(state.session?.sample_count||hw.received_samples||Object.values(state.samples).reduce((n,r)=>n+r.length,0)).toLocaleString()} samples${state.session?' saved':' in view'}`;$('footer-storage').textContent=server.library_path||'Durable local session storage';$('local-status').innerHTML=`<i style="background:${rec.error?'var(--red)':'var(--teal)'}"></i> ${rec.error?'Save error':server.queue_depth>0?'Saving locally…':rec.armed?'Saving continuously':'Saved locally'}`;$('waveform-units').textContent=`${nativeUnits()==='counts'?'Native device counts':nativeUnits()} · ${state.session?.sample_rate||hw.sample_rate||'—'} Hz · ${state.live?'receive-time estimates':'recorded sample timeline'}`;const details={transport:hw.transport,source:hw.source,devices:hw.devices,firmware:hw.firmware,samples_arriving:hw.samples_arriving,sample_age_seconds:hw.sample_age_seconds,configuration:hw.configuration,passive_mode:hw.passive_mode,lead_off:hw.lead_off,units:hw.units,error:hw.error};$('hardware-details').textContent=Object.entries(details).filter(([,v])=>v!=null).map(([k,v])=>`${k.replaceAll('_',' ')}: ${typeof v==='object'?JSON.stringify(v):v}`).join('\n');renderChannels()}
let lastChannelKey='';function renderChannels(){const names=Object.keys(state.samples);const key=names.join('|')+'|'+[...state.hidden].join('|');if(key===lastChannelKey)return;lastChannelKey=key;$('channel-chips').innerHTML=names.map((name,i)=>`<label class="channel-chip" style="--channel-color:${colors[i%colors.length]}"><input type="checkbox" data-channel="${esc(name)}" ${state.hidden.has(name)?'':'checked'}><span>${esc(name)}</span><span class="unit-label">${esc(nativeUnits())}</span></label>`).join('');$$('[data-channel]').forEach(input=>input.onchange=()=>{input.checked?state.hidden.delete(input.dataset.channel):state.hidden.add(input.dataset.channel);drawAll()})}
let labelSignature='';function renderLabels(force=false){const search=$('label-search').value.toLowerCase();const signature=JSON.stringify(state.labels)+state.selectedLabel+search;if(!force&&signature===labelSignature)return;labelSignature=signature;$('label-list').innerHTML=state.labels.filter(l=>l.name.toLowerCase().includes(search)).map(l=>`<button class="label-choice ${l.id===state.selectedLabel?'selected':''}" data-label-id="${esc(l.id)}" title="${esc(l.description||l.name)}"><i class="color-dot" style="background:${esc(l.color||'#94a3b8')}"></i><span>${esc(l.name)}</span>${l.shortcut?`<kbd>${esc(l.shortcut)}</kbd>`:''}</button>`).join('');$$('[data-label-id]').forEach(button=>button.onclick=()=>selectLabel(button.dataset.labelId));$('session-label-filter').innerHTML='<option value="">All conditions</option>'+state.labels.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');$$('.label-select').forEach(el=>fillSelect(el.id,labelOptionHtml()));if(!$('protocol-steps').children.length)renderProtocolSteps()}
async function selectLabel(id){await action('select_label',{label_id:id,scope:scopeValue()});state.selectedLabel=id;renderLabels(true);await poll()}
const scopeValue=()=> $('label-scope').value==='channels'?activeChannels():$('label-scope').value;
async function toggleSection(){await action('section_toggle',{session_id:state.server?.recording?.session_id,label_id:state.selectedLabel,scope:scopeValue(),countdown:Number($('label-countdown').value),client_wall_ms:Date.now()});await refreshSession();await poll()}
async function toggleRecording(){if(state.server?.recording?.armed){await action('record_stop',{},'Recording saved locally.');state.live=false;state.paused=true;state.sessionId=state.server.recording.session_id;await refreshSession();state.end=Math.max(state.window,sessionDuration());await loadSamples();await poll()}else{recordDetails(true)}}
function recordDetails(start=false){openModal(start?'Start a recording':'Session details',`<p class="small-copy">${start?'Recording and section labels are independent. The timeline begins with the first received sample.':'Saved session details are read-only. The portable export preserves the original title and participant ID.'}</p><label class="field-label">Session title</label><input id="session-title" ${!start?'readonly aria-readonly="true"':''} value="${esc(start?'Placement exploration':state.session?.title||'Placement exploration')}"><label class="field-label">Pseudonymous participant ID</label><input id="participant-id" ${!start?'readonly aria-readonly="true"':''} placeholder="e.g. P001" value="${esc((start?state.settings.participant:state.session?.participant)||'')}">${!start&&state.session?`<dl class="details-list"><dt>Session</dt><dd>${esc(state.session.id)}</dd><dt>Source</dt><dd>${esc(state.session.source)}</dd><dt>Timing</dt><dd>${esc(state.session.timing)}</dd><dt>Firmware processing</dt><dd>${esc(state.session.upstream_processing)}</dd><dt>Saved samples</dt><dd>${Number(state.session.sample_count).toLocaleString()}</dd></dl>`:''}`,start?[{text:'Cancel',action:closeModal},{text:'Start recording',primary:true,action:async()=>{const participant=$('participant-id').value.trim();await action('settings',{settings:{participant}});const session=await action('record_start',{title:$('session-title').value.trim()||'Untitled experiment',participant});state.sessionId=session.id;state.session=session;state.live=true;state.paused=false;state.processed=null;state.results=[];$('processed-name').textContent='No pipeline selected';$('processed-note').textContent='Run processing on saved samples to inspect aligned results.';state.annotations=[];state.events=[];state.selection=null;closeModal();await poll();toast('Recording armed. Waiting for the first received sample.')}}]:[{text:'Close',action:closeModal},{text:'Export complete session',primary:true,action:()=>exportSession(state.sessionId)}]);if(!start){$('session-title').readOnly=true;$('participant-id').readOnly=true}}
function renderAnnotations(){$('annotation-count').textContent=`${state.annotations.length} section${state.annotations.length===1?'':'s'}`;$('annotations-table').innerHTML=state.annotations.length?state.annotations.map(a=>`<tr data-annotation="${esc(a.id)}"><td><span class="label-name"><i class="color-dot" style="background:${esc(a.color||'#95a8b6')}"></i>${esc(a.label||'Unnamed section')}</span></td><td class="annotation-time">${formatTime(a.start,true)} — ${formatTime(a.end,true)}<br><span class="muted">${durationLabel(a.end-a.start)}</span></td><td>${esc(Array.isArray(a.scope)?a.scope.join(', '):a.scope||'both')}</td><td><span class="status-label ${a.needs_review?'review':''}">${esc(a.source||'manual')} · ${a.needs_review?'review':a.reviewed?'reviewed':'unconfirmed'}</span></td><td><button class="text-button" data-edit="${esc(a.id)}">Edit ↗</button></td></tr>`).join(''):'<tr><td colspan="5" class="table-empty">Press <kbd>Space</kbd> to mark a section while recording.</td></tr>';$$('[data-edit]').forEach(b=>b.onclick=()=>editAnnotation(state.annotations.find(a=>a.id===b.dataset.edit)));renderCoverage()}
function editAnnotation(annotation=null){if(!state.sessionId){toast('Record or open a session before adding a section.','warning');return}const selected=state.selection||{start:Math.max(0,visibleRange().start),end:Math.min(sessionDuration(),visibleRange().end)};const a=annotation||{...selected,label_id:state.selectedLabel,source:'manual',scope:scopeValue(),needs_review:true};if(a.end<=a.start){toast('A section needs recorded samples and a positive duration.','warning');return}openModal(annotation?'Edit section':'Label selected range',`<label class="field-label">Condition</label><select id="edit-label">${labelOptionHtml()}</select><div class="form-row"><label>Start · seconds<input id="edit-start" type="number" min="0" step="0.001" value="${a.start.toFixed(3)}"></label><label>End · seconds<input id="edit-end" type="number" min="0" step="0.001" value="${a.end.toFixed(3)}"></label></div><label class="field-label">Scope</label><select id="edit-scope"><option value="both">Both ears</option><option value="left">Left ear</option><option value="right">Right ear</option><option value="channels">Selected channels</option></select><label class="field-label">Notes</label><textarea id="edit-notes" rows="3" placeholder="Describe what you observed…">${esc(a.notes||'')}</textarea><div class="form-row"><label>Boundary uncertainty ± seconds<input id="edit-uncertainty" type="number" min="0" step="0.1" value="${a.boundary_uncertainty||0}"></label><label>Observed signal issue<input id="edit-issue" value="${esc(a.issue||'')}" placeholder="Optional; separate from placement"></label></div><label class="checkbox-label"><input id="edit-reviewed" type="checkbox" ${a.reviewed&&a.source!=='protocol'?'checked':''}> ${a.source==='protocol'?'I confirm I performed this action and reviewed its boundaries':'I reviewed this observation and its boundaries'}</label><p class="small-copy">Source: ${esc(a.source||'manual')}. ${a.source==='protocol'?'Explicit confirmation saves a manual observation and retains its scheduled origin and previous version.':'Review preserves the annotation source and previous versions.'} Samples never change.</p>${annotation?'<div class="button-row"><button class="button" id="split-section">Split section</button><button class="button" id="merge-section">Merge adjacent</button><button class="button" id="annotation-history">View history</button></div>':''}`,[...(annotation?[{text:'Delete section',danger:true,action:async()=>{await action('annotation_delete',{session_id:state.sessionId,id:a.id},'Section removed. Raw samples preserved.');closeModal();await refreshSession()}}]:[]),{text:'Cancel',action:closeModal},{text:'Save section',primary:true,action:async()=>{const label=state.labels.find(l=>l.id===$('edit-label').value)||{};const reviewed=$('edit-reviewed').checked;const updated={...a,...(reviewed&&a.source==='protocol'?{source:'manual',origin_source:'protocol',original_protocol_annotation_id:a.original_protocol_annotation_id||a.id}:{}),label_id:label.id||null,label:label.name||'Unnamed section',color:label.color||'#94a3b8',placement:label.placement||'',activity:label.activity||'',issue:$('edit-issue').value,start:Number($('edit-start').value),end:Number($('edit-end').value),scope:$('edit-scope').value==='channels'?activeChannels():$('edit-scope').value,notes:$('edit-notes').value,reviewed,needs_review:!reviewed,boundary_uncertainty:Number($('edit-uncertainty').value)};await action('annotation',{session_id:state.sessionId,annotation:updated},'Section saved.');closeModal();state.selection=null;await refreshSession()}}]);$('edit-label').value=a.label_id||'';$('edit-scope').value=Array.isArray(a.scope)?'channels':a.scope||'both';if(annotation){bind('split-section',()=>splitAnnotation(a));bind('merge-section',()=>mergeAnnotation(a));bind('annotation-history',()=>showHistory(a.id))}}
function splitAnnotation(a){openModal('Split section',`<p class="small-copy">Choose a boundary inside ${formatTime(a.start,true)} — ${formatTime(a.end,true)}.</p><label class="field-label">Split at · seconds</label><input type="number" id="split-point" min="${a.start}" max="${a.end}" step="0.001" value="${((a.start+a.end)/2).toFixed(3)}">`,[{text:'Cancel',action:closeModal},{text:'Split',primary:true,action:async()=>{await action('annotation_split',{session_id:state.sessionId,id:a.id,t:Number($('split-point').value)},'Section split.');closeModal();await refreshSession()}}])}
function mergeAnnotation(a){const adjacent=state.annotations.filter(b=>b.id!==a.id&&b.label_id===a.label_id&&JSON.stringify(b.scope)===JSON.stringify(a.scope)&&b.source===a.source&&b.start<=a.end+1e-6&&b.end>=a.start-1e-6);if(!adjacent.length){toast('No touching section has the same label, scope and source.','warning');return}openModal('Merge adjacent section',`<p class="small-copy">Only touching or overlapping sections with matching label, scope and source can merge.</p><label class="field-label">Adjacent section</label><select id="merge-id">${adjacent.map(b=>`<option value="${esc(b.id)}">${esc(b.label)} · ${formatTime(b.start,true)} — ${formatTime(b.end,true)}</option>`).join('')}</select>`,[{text:'Cancel',action:closeModal},{text:'Merge',primary:true,action:async()=>{await action('annotation_merge',{session_id:state.sessionId,ids:[a.id,$('merge-id').value]},'Sections merged.');closeModal();await refreshSession()}}])}
function showHistory(id){const history=state.history.filter(h=>h.before?.id===id||h.after?.id===id);openModal('Annotation edit history',history.length?history.map(h=>`<div class="history-item">${dateLabel(h.wall_ns/1e9)} · ${h.undone?'undone':'saved'}<pre>${esc(JSON.stringify({before:h.before,after:h.after},null,2))}</pre></div>`).join(''):'<p class="small-copy">No history for this section.</p>',[{text:'Close',action:closeModal}])}
function labelEditor(existing=null){const label=existing||{};openModal(existing?'Edit label':'Create a label',`<label class="field-label">Name</label><input id="new-label-name" value="${esc(label.name||'')}" placeholder="e.g. Left earbud on table"><label class="field-label">Description</label><textarea id="new-label-description" rows="2">${esc(label.description||'')}</textarea><div class="form-row"><label>Color<input type="color" id="new-label-color" value="${esc(label.color||colors[state.labels.length%colors.length])}"></label><label>Shortcut<input id="new-label-shortcut" value="${esc(label.shortcut||'')}" placeholder="Optional key" maxlength="12"></label></div><div class="form-row"><label>Placement<input id="new-label-placement" value="${esc(label.placement||'')}" placeholder="e.g. in ear"></label><label>Activity<input id="new-label-activity" value="${esc(label.activity||'')}" placeholder="e.g. moving"></label></div><label class="field-label">Observed signal issue (optional)</label><input id="new-label-issue" value="${esc(label.issue||'')}" placeholder="Keep observation separate from model prediction">`,[{text:'Cancel',action:closeModal},{text:existing?'Save changes':'Create label',primary:true,action:async()=>{const name=$('new-label-name').value.trim();if(!name){toast('Enter a label name.','warning');return}const shortcut=$('new-label-shortcut').value.trim();if(shortcut&&Object.values({...EEGShortcuts.defaults,...state.settings.shortcuts}).some(k=>k.toLowerCase()===shortcut.toLowerCase())){toast('That key is reserved by a recording or viewer shortcut.','warning');return}if(shortcut&&state.labels.some(l=>l.id!==label.id&&l.shortcut?.toLowerCase()===shortcut.toLowerCase())){toast('Another label already uses that shortcut.','warning');return}const saved={...label,id:label.id||crypto.randomUUID().replaceAll('-',''),name,description:$('new-label-description').value,color:$('new-label-color').value,shortcut,placement:$('new-label-placement').value,activity:$('new-label-activity').value,issue:$('new-label-issue').value};state.labels=await action('labels',{labels:existing?state.labels.map(l=>l.id===label.id?saved:l):[...state.labels,saved]},'Label set saved.');closeModal();renderLabels(true);await selectLabel(saved.id)}}])}
function manageLabels(){openModal('Reusable label sets',`<label class="field-label">Edit a label</label><select id="manage-label-id">${labelOptionHtml(false)}</select><button id="edit-existing-label" class="button" style="margin-top:10px">Edit selected label</button><label class="field-label">Saved label sets</label><select id="saved-label-set"><option value="">Choose a saved set…</option>${Object.keys(state.settings.label_sets||{}).map(n=>`<option>${esc(n)}</option>`).join('')}</select><button id="load-label-set" class="button" style="margin-top:10px">Load selected set</button><label class="field-label">Save current labels as</label><input id="label-set-name" placeholder="e.g. Placement study">`,[{text:'Close',action:closeModal},{text:'Save label set',primary:true,action:async()=>{const name=$('label-set-name').value.trim();if(!name){toast('Name this label set.','warning');return}state.settings=await action('settings',{settings:{label_sets:{...state.settings.label_sets,[name]:state.labels}}},'Reusable label set saved.');closeModal()}}]);bind('edit-existing-label',()=>labelEditor(state.labels.find(l=>l.id===$('manage-label-id').value)));bind('load-label-set',async()=>{const labels=state.settings.label_sets?.[$('saved-label-set').value];if(!labels)return;state.labels=await action('labels',{labels},'Label set loaded. Existing annotations retain their labels.');closeModal();renderLabels(true)})}
function shortcutGuide(){const names={section:'Start / stop section',marker:'Add event marker',previous:'Mark previous seconds',pause:'Pause / resume viewer',undo:'Undo annotation edit',cancel:'Cancel current annotation',help:'Show this guide'};openModal('Keyboard shortcuts',`<p class="small-copy">Shortcuts follow the acquisition timeline. Pausing the viewer never pauses recording. Held keys and typing in fields are ignored.</p><table class="shortcut-table"><tbody>${Object.entries(names).map(([key,name])=>`<tr><td>${esc(name)}</td><td><input data-shortcut="${key}" value="${esc(state.settings.shortcuts?.[key]||EEGShortcuts.defaults[key])}" aria-label="Shortcut for ${esc(name)}"></td></tr>`).join('')}<tr><td>Select / switch favorite label</td><td><kbd>1</kbd> — <kbd>9</kbd></td></tr></tbody></table><label class="field-label">Previous interval · seconds</label><input id="shortcut-previous" type="number" min="0.1" max="600" step="0.5" value="${state.settings.previous_seconds||10}"><p class="small-copy">Use Space, Escape, ?, a letter, or Mod+Z (⌘ on Mac / Ctrl elsewhere). Label keys are editable in the label manager.</p>`,[{text:'Reset defaults',action:()=>{$$('[data-shortcut]').forEach(el=>el.value=EEGShortcuts.defaults[el.dataset.shortcut])}},{text:'Save shortcuts',primary:true,action:async()=>{const shortcuts=Object.fromEntries($$('[data-shortcut]').map(el=>[el.dataset.shortcut,el.value.trim()]));const vals=Object.values(shortcuts).map(s=>s.toLowerCase());if(vals.some(v=>!v)||new Set(vals).size!==vals.length){toast('Choose a unique nonempty shortcut for each action.','warning');return}state.settings=await action('settings',{settings:{shortcuts,previous_seconds:Number($('shortcut-previous').value)}},'Keyboard settings saved.');closeModal()}}])}
async function markerDialog(){if(!state.sessionId){toast('Record or open a session first.','warning');return}openModal('Add event marker',`<label class="field-label">What happened?</label><input id="marker-text" value="Event marker" placeholder="e.g. Adjusted left earbud"><p class="small-copy">${state.server?.recording?.armed?'The server assigns the marker to the latest acquired sample when saved.':'The marker will use the current inspected time.'}</p>`,[{text:'Cancel',action:closeModal},{text:'Save marker',primary:true,action:async()=>{await action('marker',{session_id:state.sessionId,label:$('marker-text').value||'Event marker',...(!state.server?.recording?.armed?{t:Math.min(sessionDuration(),state.hover?.t??visibleRange().start)}:{})},'Marker saved.');closeModal();await refreshSession()}}])}
async function quickMarker(){if(!state.sessionId){toast('Record or open a session first.','warning');return}await action('marker',{session_id:state.sessionId,label:'Event marker',...(!state.server?.recording?.armed?{t:Math.min(sessionDuration(),state.hover?.t??visibleRange().start)}:{})},'Event marker saved.');await refreshSession()}
async function markPrevious(){const seconds=Number(state.settings.previous_seconds||10);if(state.server?.recording?.armed){await action('mark_previous',{seconds},`Previous ${seconds} seconds marked for review.`);await refreshSession()}else if(state.sessionId){const end=Math.min(sessionDuration(),state.hover?.t??state.end);state.selection={start:Math.max(0,end-seconds),end};editAnnotation()}else toast('Record or open a session first.','warning')}
async function togglePause(){state.paused=!state.paused;if(!state.live&&!state.paused&&state.end>=sessionDuration())state.end=state.window;if(state.live&&!state.paused){state.samples=state.server?.live?.channels||{};state.end=Math.max(state.window,latestLive())}renderLiveState();drawAll()}
async function returnLive(){state.live=true;state.paused=false;state.selection=null;state.processed=null;$('processed-name').textContent='No pipeline selected';$('processed-note').textContent='Saved processing is available when reviewing its recorded session.';if(state.server?.recording?.armed){state.sessionId=state.server.recording.session_id;state.session=state.server.active_session;await refreshSession()}else{state.sessionId=null;state.session=null;state.annotations=[];state.events=[];renderAnnotations()}state.samples=state.server?.live?.channels||{};renderLiveState();drawAll()}
async function undo(){if(!state.sessionId){toast('Open a session to undo annotation edits.','warning');return}const result=await action('undo',{session_id:state.sessionId});toast(result?'Annotation change undone. Raw data unchanged.':'No annotation changes to undo.');await refreshSession()}
document.addEventListener('keydown',async e=>{if($('modal').open)return;const command=EEGShortcuts.command(e,state.settings.shortcuts,state.labels);if(!command)return;e.preventDefault();try{if(command.action==='label')await selectLabel(command.label.id);else if(command.action==='section')await toggleSection();else if(command.action==='marker')await quickMarker();else if(command.action==='previous')await markPrevious();else if(command.action==='pause')await togglePause();else if(command.action==='undo')await undo();else if(command.action==='cancel'){state.selection=null;await action('cancel_section');await poll();drawAll()}else if(command.action==='help')shortcutGuide()}catch(error){console.error(error)}});
function canvasContext(canvas){const bounds=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;const width=Math.max(1,bounds.width),height=Math.max(1,bounds.height);if(canvas.width!==Math.round(width*ratio)||canvas.height!==Math.round(height*ratio)){canvas.width=Math.round(width*ratio);canvas.height=Math.round(height*ratio)}const ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,width,height);return{ctx,width,height}}
function commonScales(channels,range){const fixed=$('amplitude-mode').value==='fixed',value=Math.max(0.001,Number($('amplitude-value').value)||500);return Object.fromEntries(channels.map(ch=>{const rows=state.samples[ch]||[];let max=0;for(const row of rows)if(row.t>=range.start&&row.t<=range.end&&Number.isFinite(row.value))max=Math.max(max,Math.abs(row.value));return[ch,fixed?value:Math.max(1,max*1.12)]}))}
function drawSignal(canvas,channels,scales,processed=false){const{ctx,width,height}=canvasContext(canvas),range=visibleRange(),left=66,right=15,top=14,bottom=29,plotWidth=width-left-right,plotHeight=height-top-bottom;ctx.fillStyle='#12202c';ctx.fillRect(0,0,width,height);ctx.font='9px "IBM Plex Mono", monospace';ctx.textBaseline='middle';const rowCount=Math.max(2,channels.length),rowHeight=plotHeight/rowCount;const step=state.window<=5?1:state.window<=15?2:state.window<=30?5:state.window<=60?10:20;ctx.lineWidth=1;for(let t=Math.ceil(range.start/step)*step;t<=range.end;t+=step){const x=left+(t-range.start)/state.window*plotWidth;ctx.strokeStyle='#263644';ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,height-bottom);ctx.stroke();ctx.fillStyle='#6e8597';ctx.textAlign='center';ctx.fillText(`${t.toFixed(state.window<=5?1:0)} s`,x,height-12)}for(let row=0;row<rowCount;row++){const y=top+(row+.5)*rowHeight;ctx.strokeStyle='#263746';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(width-right,y);ctx.stroke();for(const offset of [-.32,.32]){ctx.strokeStyle='#1c2e3c';ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(left,y+rowHeight*offset);ctx.lineTo(width-right,y+rowHeight*offset);ctx.stroke();ctx.setLineDash([])}if(channels[row]){const name=channels[row],index=Object.keys(state.samples).indexOf(name);ctx.textAlign='left';ctx.fillStyle=colors[Math.max(0,index)%colors.length];const lines=name.replace(/Left/i,'L').replace(/Right/i,'R').split(/[ /:_]+/);ctx.fillText(lines.join(' ').slice(0,10),9,y-9);ctx.fillStyle='#718a9d';ctx.font='8px "IBM Plex Mono", monospace';ctx.fillText(`±${scales[name]>=1000?(scales[name]/1000).toFixed(1)+'k':scales[name].toFixed(scales[name]<10?1:0)}`,9,y+7);ctx.font='9px "IBM Plex Mono", monospace';}}
// Draw recorded sections and explicit gaps behind signal paths.
ctx.save();ctx.beginPath();ctx.rect(left,top,plotWidth,plotHeight);ctx.clip();for(const a of state.annotations){if(a.end<range.start||a.start>range.end)continue;const x=left+(a.start-range.start)/state.window*plotWidth,w=(a.end-a.start)/state.window*plotWidth;ctx.globalAlpha=.07;ctx.fillStyle=a.color||'#93a7b6';ctx.fillRect(x,top,w,plotHeight);ctx.globalAlpha=1;ctx.strokeStyle=(a.color||'#93a7b6')+'70';ctx.setLineDash(a.source==='protocol'?[4,4]:[]);ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,height-bottom);ctx.stroke();ctx.setLineDash([])}const gaps=state.events.filter(e=>e.kind==='gap'||e.type==='gap').map(e=>e.data||e);for(const gap of gaps){const x=left+(gap.start-range.start)/state.window*plotWidth,w=Math.max(2,(gap.end-gap.start)/state.window*plotWidth);ctx.fillStyle='#ce838320';ctx.fillRect(x,top,w,plotHeight)}
const fs=Number(state.session?.sample_rate||state.server?.hardware?.sample_rate||250);channels.forEach((ch,i)=>{const data=processed?state.processed?.channels?.find(c=>c.channel===ch):null;const rows=processed?(data?data.times.map((t,j)=>({t,value:data.processed[j]})):[]):state.samples[ch]||[];const y=top+(i+.5)*rowHeight,scale=scales[ch];ctx.lineWidth=1.15;ctx.strokeStyle=colors[Math.max(0,Object.keys(state.samples).indexOf(ch))%colors.length];ctx.beginPath();let previous=null;const gapThreshold=Math.max(3/fs,state.window/plotWidth*12);for(const sample of rows){if(sample.t<range.start-1/fs||sample.t>range.end+1/fs)continue;const x=left+(sample.t-range.start)/state.window*plotWidth,value=sample.value==null?NaN:Number(sample.value);const interrupted=previous&&(sample.t-previous.t>gapThreshold||gaps.some(g=>(!g.channel||g.channel===ch)&&g.start>=previous.t&&g.start<sample.t));if(!Number.isFinite(value)){previous=null;continue}const py=y-value/scale*rowHeight*.39;if(!previous||interrupted)ctx.moveTo(x,py);else ctx.lineTo(x,py);previous=sample}ctx.stroke()});if(state.selection){const x=left+(state.selection.start-range.start)/state.window*plotWidth,w=(state.selection.end-state.selection.start)/state.window*plotWidth;ctx.fillStyle='#96cde32b';ctx.fillRect(x,top,w,plotHeight);ctx.strokeStyle='#9dc7dc';ctx.setLineDash([3,3]);ctx.strokeRect(x,top,w,plotHeight);ctx.setLineDash([])}if(state.hover){const x=left+(state.hover.t-range.start)/state.window*plotWidth;ctx.strokeStyle='#9aadb477';ctx.setLineDash([3,4]);ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,height-bottom);ctx.stroke();ctx.setLineDash([])}ctx.restore();}
function drawTimeline(){const{ctx,width,height}=canvasContext($('session-timeline'));ctx.fillStyle='#121f2a';ctx.fillRect(0,0,width,height);const left=17,right=17,total=Math.max(state.window,sessionDuration(),state.live?latestLive():0),plotWidth=width-left-right;ctx.font='8px monospace';ctx.fillStyle='#698092';ctx.textAlign='center';for(let i=0;i<=6;i++){const t=total/6*i,x=left+i/6*plotWidth;ctx.strokeStyle='#233442';ctx.beginPath();ctx.moveTo(x,8);ctx.lineTo(x,height-18);ctx.stroke();ctx.fillText(formatTime(t),x,height-5)}ctx.fillStyle='#253a48';ctx.fillRect(left,28,plotWidth,17);for(const a of state.annotations){const x=left+a.start/total*plotWidth,w=Math.max(1,(a.end-a.start)/total*plotWidth);ctx.globalAlpha=a.source==='protocol'?.6:.8;ctx.fillStyle=a.color||'#94a3b8';ctx.fillRect(x,25,w,23);ctx.globalAlpha=1;if(a.needs_review){ctx.strokeStyle='#efd796';ctx.setLineDash([2,2]);ctx.strokeRect(x,25,w,23);ctx.setLineDash([])}}for(const e of state.events){if(e.kind==='marker'){const x=left+(e.t||0)/total*plotWidth;ctx.strokeStyle='#f1d094';ctx.beginPath();ctx.moveTo(x,14);ctx.lineTo(x,54);ctx.stroke()}if(e.kind==='gap'){const d=e.data||{};ctx.fillStyle='#ed929299';ctx.fillRect(left+(d.start||e.t||0)/total*plotWidth,20,Math.max(2,((d.end||0)-(d.start||0))/total*plotWidth),32)}}if(state.server?.section&&state.sessionId===state.server.recording?.session_id){const a=state.server.section;ctx.fillStyle='#7ae0c077';ctx.fillRect(left+a.start/total*plotWidth,25,Math.max(1,(sessionDuration()-a.start)/total*plotWidth),23)}const range=visibleRange();ctx.strokeStyle='#b4c7d4';ctx.lineWidth=1;ctx.strokeRect(left+range.start/total*plotWidth,9,Math.min(plotWidth,(range.end-range.start)/total*plotWidth),52);$('timeline-duration').textContent=formatTime(sessionDuration());}
function drawAll(){if(state.view!=='viewer')return;const channels=activeChannels(),range=visibleRange(),scales=commonScales(channels,range);drawSignal($('waveform'),channels,scales);if(state.paired)drawSignal($('processed-waveform'),channels,scales,true);$('waveform-empty').hidden=Object.values(state.samples).some(r=>r.length>0);$('waveform-range').textContent=`${range.start.toFixed(3)} — ${range.end.toFixed(3)} s`;drawTimeline()}
function eventTime(e){const rect=$('waveform').getBoundingClientRect(),x=Math.max(0,Math.min(rect.width-81,e.clientX-rect.left-66));return visibleRange().start+x/(rect.width-81)*state.window}
$('waveform').addEventListener('pointerdown',e=>{if(!state.sessionId)return;state.paused=true;state.drag={t:eventTime(e),x:e.clientX};$('waveform').setPointerCapture(e.pointerId);state.selection={start:state.drag.t,end:state.drag.t};renderLiveState()});
$('waveform').addEventListener('pointermove',e=>{const t=eventTime(e);state.hover={t};if(state.drag){state.selection={start:Math.max(0,Math.min(t,state.drag.t)),end:Math.min(sessionDuration(),Math.max(t,state.drag.t))}}const channels=activeChannels(),rect=$('waveform').getBoundingClientRect(),rowHeight=(rect.height-43)/Math.max(2,channels.length),ch=channels[Math.max(0,Math.min(channels.length-1,Math.floor((e.clientY-rect.top-14)/rowHeight)))],rows=state.samples[ch]||[];let closest=null;for(const row of rows)if(!closest||Math.abs(row.t-t)<Math.abs(closest.t-t))closest=row;const readout=$('cursor-readout');readout.hidden=false;readout.textContent=closest?`${closest.t.toFixed(6)} s · ${ch} · ${Number(closest.value).toFixed(3)} ${nativeUnits()} · index ${closest.idx??'—'}`:`${t.toFixed(3)} s`;drawAll()});
$('waveform').addEventListener('pointerup',e=>{if(!state.drag)return;const width=Math.abs(e.clientX-state.drag.x);state.drag=null;if(width>5&&state.selection?.end>state.selection.start)editAnnotation();else state.selection=null;drawAll()});
$('waveform').addEventListener('pointerleave',()=>{if(!state.drag){state.hover=null;$('cursor-readout').hidden=true;drawAll()}});
$('session-timeline').addEventListener('click',async e=>{if(!state.sessionId)return;const rect=e.currentTarget.getBoundingClientRect(),total=Math.max(state.window,sessionDuration()),t=Math.max(0,Math.min(1,(e.clientX-rect.left-17)/(rect.width-34)))*total;state.live=false;state.paused=true;state.end=Math.max(state.window,Math.min(sessionDuration(),t+state.window/2));await loadSamples();renderLiveState()});
window.addEventListener('resize',drawAll);
async function pan(direction){state.paused=true;const max=Math.max(state.window,sessionDuration(),state.live?latestLive():0);state.end=Math.max(state.window,Math.min(max,state.end+direction*state.window*.7));if(state.sessionId){state.live=false;await loadSamples()}renderLiveState();drawAll()}
async function jumpNext(){if(!state.sessionId)return;const type=$('jump-type').value,current=visibleRange().start+.001;const points=type==='annotation'?state.annotations.map(a=>a.start):state.events.filter(e=>type==='gap'?e.kind==='gap':e.kind!=='packet').map(e=>e.t).filter(t=>Number.isFinite(t));points.sort((a,b)=>a-b);const t=points.find(t=>t>current)??points[0];if(t==null){toast(`No ${type}s in this session.`,'warning');return}state.paused=true;state.live=false;state.end=Math.max(state.window,Math.min(sessionDuration(),t+state.window*.8));await loadSamples();renderLiveState()}
let playbackTick=performance.now();setInterval(async()=>{const now=performance.now(),delta=(now-playbackTick)/1000;playbackTick=now;if(!state.live&&!state.paused&&state.sessionId){state.end+=delta*Number($('playback-speed').value);if(state.end>=sessionDuration()){state.end=Math.max(state.window,sessionDuration());state.paused=true;renderLiveState()}await loadSamples()}},100);

async function refreshLibrary(){try{state.sessions=await api('/api/sessions');renderSessionSelects();renderLibrary();if(state.view==='experiments')await refreshCoverage()}catch(error){toast(error.message,'error')}}
function renderSessionSelects(){const html=state.sessions.length?state.sessions.map(s=>`<option value="${esc(s.id)}">${esc(s.title)} · ${esc(s.participant||'No participant')} · ${dateLabel(s.created_at)}</option>`).join(''):'<option value="">No saved sessions</option>';$$('.session-select').forEach(el=>{const selected=[...el.selectedOptions].map(o=>o.value);el.innerHTML=html;[...el.options].forEach(o=>o.selected=selected.includes(o.value));if(!selected.length&&state.sessionId)[...el.options].forEach(o=>o.selected=o.value===state.sessionId);if(!el.multiple&&!el.value&&el.options.length)el.selectedIndex=0})}
let sessionDetailsCache=new Map();async function renderLibrary(){const query=$('session-search').value.toLowerCase(),date=$('session-date').value,label=$('session-label-filter').value,review=$('session-review-filter').value;if((label||review)&&state.sessions.some(s=>!sessionDetailsCache.has(s.id)||sessionDetailsCache.get(s.id).session.revision!==s.revision)){await Promise.all(state.sessions.map(async s=>{if(!sessionDetailsCache.has(s.id)||sessionDetailsCache.get(s.id).session.revision!==s.revision)sessionDetailsCache.set(s.id,await api(`/api/session?id=${s.id}`))}))}const sessions=state.sessions.filter(s=>{const searchable=[s.title,s.participant,s.id,JSON.stringify(s.acquisition)].join(' ').toLowerCase();const details=sessionDetailsCache.get(s.id);return(!query||searchable.includes(query))&&(!date||new Date(s.created_at*1000).toLocaleDateString('en-CA')===date)&&(!label||details?.annotations.some(a=>a.label_id===label))&&(!review||details?.annotations.some(a=>a.needs_review))});const total=state.sessions.reduce((n,s)=>n+s.duration,0);$('library-stats').innerHTML=[['SESSIONS',state.sessions.length,'Full recordings, preserved'],['RECORDED TIME',durationLabel(total),'Across all saved sessions'],['PARTICIPANTS',new Set(state.sessions.map(s=>s.participant).filter(Boolean)).size,'Pseudonymous identifiers'],['RAW SAMPLES',state.sessions.reduce((n,s)=>n+s.sample_count,0).toLocaleString(),'Incrementally saved to disk']].map(([title,value,note])=>`<div class="stat-card"><span>${title}</span><strong>${value}</strong><small>${note}</small></div>`).join('');$('session-library').innerHTML=sessions.length?sessions.map(s=>`<article class="session-card" data-session="${esc(s.id)}" tabindex="0" role="button" aria-label="Open ${esc(s.title)}"><div class="card-top"><span>${dateLabel(s.created_at)}</span><span class="mode-badge ${/simulat/.test(s.source)?'simulated':''}">${esc(s.source)}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.participant||'No participant ID')} · ${s.channels?.length||0} channels · ${s.sample_rate||'—'} Hz</p><div class="card-bottom"><span>${durationLabel(s.duration)} · ${esc(s.status)}</span><span>Open session ↗</span></div></article>`).join(''):'<div class="empty-state"><h3>No sessions found</h3><p>Record your first experiment or adjust the search filters.</p></div>';$$('[data-session]').forEach(card=>{card.onclick=()=>openSession(card.dataset.session);card.onkeydown=e=>{if(e.key==='Enter')openSession(card.dataset.session)}})}
async function exportSession(id){if(!id){toast('Open a saved session first.','warning');return}try{const response=await fetch(`/api/export?id=${encodeURIComponent(id)}`);if(!response.ok){const err=await response.json();throw new Error(err.error)}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=response.headers.get('Content-Disposition')?.match(/filename="(.+)"/)?.[1]||`${id}.zip`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Portable session export prepared with signals, metadata and annotations.')}catch(error){toast(error.message,'error')}}
