let protocolSteps=[];function renderProtocolSteps(){if(!protocolSteps.length){const saved=state.settings.protocol?.steps;protocolSteps=saved||[{label_id:state.labels[0]?.id,duration:30},{label_id:state.labels[1]?.id,duration:20},{label_id:state.labels.find(l=>/table/i.test(l.name))?.id,duration:30},{label_id:state.labels.find(l=>/fingertip/i.test(l.name))?.id,duration:20}]}$('protocol-steps').innerHTML=protocolSteps.map((step,i)=>`<div class="protocol-step"><span>${String(i+1).padStart(2,'0')}</span><select data-step-label="${i}" aria-label="Step ${i+1} condition">${labelOptionHtml(false)}</select><input data-step-duration="${i}" type="number" min="1" max="3600" value="${step.duration}" aria-label="Step ${i+1} duration in seconds" title="Duration in seconds"><button class="icon-button" data-step-remove="${i}" aria-label="Remove step ${i+1}">×</button></div>`).join('');$$('[data-step-label]').forEach(el=>{el.value=protocolSteps[Number(el.dataset.stepLabel)].label_id||state.labels[0]?.id;el.onchange=()=>protocolSteps[Number(el.dataset.stepLabel)].label_id=el.value});$$('[data-step-duration]').forEach(el=>el.onchange=()=>protocolSteps[Number(el.dataset.stepDuration)].duration=Number(el.value));$$('[data-step-remove]').forEach(el=>el.onclick=()=>{protocolSteps.splice(Number(el.dataset.stepRemove),1);renderProtocolSteps()})}
