function renderCoverage(){const sessions=[...sessionDetailsCache.values()];if(state.sessionId&&!sessions.some(s=>s.session.id===state.sessionId))sessions.push({session:state.session,annotations:state.annotations});const summary=state.labels.map(label=>{const matches=sessions.flatMap(s=>(s.annotations||[]).filter(a=>a.label_id===label.id).map(a=>({a,s:s.session})));return{label,duration:matches.reduce((n,{a})=>n+a.end-a.start,0),sections:matches.length,sessions:new Set(matches.map(m=>m.s.id)).size,participants:new Set(matches.map(m=>m.s.participant).filter(Boolean)).size}});const max=Math.max(1,...summary.map(s=>s.duration));$('coverage-list').innerHTML=summary.length?summary.map(s=>`<div class="coverage-row"><div><span>${esc(s.label.name)}</span><span style="color:${esc(s.label.color)}">${durationLabel(s.duration)}</span></div><div class="coverage-track"><i style="width:${s.duration/max*100}%;background:${esc(s.label.color)}"></i></div><small>${s.sections} sections · ${s.sessions} sessions · ${s.participants} participants${s.duration===0?' · NOT YET COLLECTED':''}</small></div>`).join(''):'<p class="muted">Create labels to track coverage.</p>'}
