function flagIntervals(channel,fs){
  const intervals=[];let start=null,previous=null;
  (channel.flags||[]).forEach((flag,i)=>{const t=channel.times[i];if(flag){if(start===null)start=t;else if(previous!==null&&t-previous>1.5/fs){intervals.push({start,end:previous+1/fs});start=t;}previous=t;}else if(start!==null){intervals.push({start,end:previous+1/fs});start=null;previous=null;}});
  if(start!==null)intervals.push({start,end:previous+1/fs});return intervals;
}
function featureValue(value){return value==null?'—':typeof value==='number'?(Math.abs(value)>=1e5||Math.abs(value)>0&&Math.abs(value)<.001?value.toExponential(3):Number(value.toFixed(4)).toLocaleString()):typeof value==='object'?JSON.stringify(value):String(value);}
function renderAnalyzed(id,result){
  const target=$(id);target.className='results-content';
  target.innerHTML=`<div class="metrics"><div class="metric"><strong>${result.channels?.length||0}</strong><small>Channels analyzed</small></div><div class="metric"><strong>${result.sample_rate||state.session?.sample_rate||'—'}</strong><small>Recorded nominal rate · Hz</small></div></div><p class="small-copy">${formatTime(result.start,true)} — ${formatTime(result.end,true)} · ${esc(result.units||'native units')}. Sampling-rate confidence follows acquisition metadata; hardware timing is not independently verified.</p>${result.channels?.map((ch,i)=>{const count=ch.flags?.filter(Boolean).length||0,intervals=flagIntervals(ch,result.sample_rate||250),features=Object.keys(ch.raw_features||{}).filter(k=>typeof ch.raw_features[k]!=='object');return `<details ${i===0?'open':''}><summary>${esc(ch.channel)} · features & spectrum</summary><canvas class="mini-plot" id="${id}-spectrum-${i}" aria-label="Power spectrum for ${esc(ch.channel)}"></canvas><div class="table-wrap"><table><thead><tr><th>Feature</th><th>Raw</th><th>Processed</th></tr></thead><tbody>${features.map(key=>`<tr><td>${esc(key.replaceAll('_',' '))}</td><td class="data-detail">${esc(featureValue(ch.raw_features[key]))}</td><td class="data-detail">${esc(featureValue(ch.processed_features?.[key]))}</td></tr>`).join('')}</tbody></table></div><p class="small-copy">${count.toLocaleString()} of ${(ch.flags?.length||0).toLocaleString()} samples flagged (${ch.flags?.length?(100*count/ch.flags.length).toFixed(2):0}%) · ${intervals.length} flagged intervals</p>${intervals.length?`<pre>${esc(intervals.slice(0,12).map(a=>formatTime(a.start,true)+' — '+formatTime(a.end,true)).join('\n'))}${intervals.length>12?'\n… '+(intervals.length-12)+' additional intervals saved':''}</pre>`:''}<details><summary>Processing and boundary details</summary><pre>${esc(JSON.stringify({boundary_regions:ch.boundaries,processing:ch.processing,removed_component_available:!!ch.removed_component},null,2))}</pre></details></details>`}).join('')||''}<details><summary>Pipeline, timing and reproducibility metadata</summary><pre>${esc(JSON.stringify({pipeline:result.pipeline,metadata:result.metadata,relationships:result.relationships,start:result.start,end:result.end,sample_rate:result.sample_rate,units:result.units},null,2))}</pre></details>`;
  requestAnimationFrame(()=>result.channels?.forEach((ch,i)=>drawSpectrum($(`${id}-spectrum-${i}`),ch.spectrum)));
}
function drawSpectrum(canvas,spectrum){if(!canvas||!spectrum)return;const{ctx,width,height}=canvasContext(canvas);const frequencies=spectrum.frequencies||[],raw=spectrum.raw||[],processed=spectrum.processed||[];const numbers=[...raw,...processed].filter(v=>v>0).map(v=>Math.log10(v));const min=Math.min(...numbers),max=Math.max(...numbers);ctx.font='9px monospace';ctx.fillStyle='#8098a8';ctx.fillText('log power · raw / processed',12,16);for(let i=0;i<=4;i++){const y=28+i*(height-52)/4;ctx.strokeStyle='#263948';ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(width-15,y);ctx.stroke()}for(const [data,color]of[[raw,colors[0]],[processed,colors[1]]]){ctx.strokeStyle=color;ctx.lineWidth=1.3;ctx.beginPath();let started=false;data.forEach((v,i)=>{if(v<=0||!Number.isFinite(v))return;const x=35+(frequencies[i]||0)/(frequencies.at(-1)||1)*(width-50),y=height-24-(Math.log10(v)-min)/(max-min||1)*(height-52);started?ctx.lineTo(x,y):ctx.moveTo(x,y);started=true});ctx.stroke()}ctx.fillStyle='#8098a8';ctx.fillText('0 Hz',30,height-7);ctx.fillText(`${Number(frequencies.at(-1)||0).toFixed(0)} Hz`,width-55,height-7)}
async function processSession(){await runResult('processing-results','run-processing',async()=>{const sessionId=$('processing-session').value;if(!sessionId)throw new Error('Choose a saved session.');const pipeline=normalizePipeline();const session=state.sessions.find(s=>s.id===sessionId);const start=Number($('processing-start').value),end=Math.min(session?.duration||30,Number($('processing-end').value));const result=await action('analyze',{session_id:sessionId,start,end,pipeline});state.processed=result;renderAnalyzed('processing-results',result);$('processed-name').textContent=pipeline.name;$('processed-note').textContent=`${pipeline.mode==='causal'?'Causal':'Offline'} processing · ${JSON.stringify(result.metadata?.timing||result.metadata?.latency||'see processing metadata for timing and boundary limits')}`;toast('Processing complete. View aligned raw and processed traces.');await openSession(sessionId);state.end=Math.max(state.window,result.start+state.window);await loadSamples();state.processed=result;state.paired=true;$('processed-panel').hidden=false;$('paired-mode').classList.add('selected');$('raw-mode').classList.remove('selected');drawAll()})}
