function renderComparisonTraces(examples){
  const results=examples.map(e=>e.candidate||e);
  const channels=[...new Set(results.flatMap(e=>(e.channels||[]).map(c=>c.channel)))];
  const sharedDuration=Math.max(.001,...results.map(r=>r.end-r.start));
  const shared={};
  for(const channel of channels){let maximum=1;for(const result of results)for(const c of result.channels||[])if(c.channel===channel)for(const values of [c.raw,c.processed])for(const value of values||[])if(Number.isFinite(value))maximum=Math.max(maximum,Math.abs(value));shared[channel]=maximum*1.1;}
  $('compare-traces').innerHTML=results.map((_,i)=>`<canvas class="mini-plot" id="compare-trace-${i}" aria-label="Example ${i?'B':'A'} waveform at shared time and amplitude scales"></canvas>`).join('');
  requestAnimationFrame(()=>results.forEach((result,i)=>{
    const {ctx,width,height}=canvasContext($(`compare-trace-${i}`)),data=result.channels||[],fs=result.sample_rate||250;
    ctx.font='9px monospace';ctx.fillStyle='#9db2c1';ctx.fillText(`EXAMPLE ${i?'B':'A'} · raw / candidate · aligned at section start`,10,15);
    const left=57,right=15,top=28,bottom=25,plotWidth=width-left-right;
    for(let tick=0;tick<=4;tick++){const x=left+tick/4*plotWidth;ctx.strokeStyle='#233744';ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,height-bottom);ctx.stroke();ctx.fillStyle='#7892a3';ctx.textAlign='center';ctx.fillText(`${(tick/4*sharedDuration).toFixed(1)} s`,x,height-7);}
    data.forEach((channel,row)=>{
      const dy=(height-top-bottom)/Math.max(1,data.length),center=top+(row+.5)*dy;
      const gaps=(result.metadata?.gaps||[]).filter(g=>!g.channel||g.channel===channel.channel);
      ctx.fillStyle=colors[row%colors.length];ctx.textAlign='left';ctx.fillText(channel.channel.replace('Left','L').replace('Right','R').slice(0,9),4,center-4);ctx.fillStyle='#7892a3';ctx.fillText('±'+shared[channel.channel].toFixed(0),4,center+9);
      ctx.strokeStyle='#29404e';ctx.beginPath();ctx.moveTo(left,center);ctx.lineTo(width-right,center);ctx.stroke();
      for(const [values,color]of[[channel.raw,colors[row%colors.length]],[channel.processed,'#e8e9e799']]){
        ctx.strokeStyle=color;ctx.lineWidth=1;ctx.beginPath();let previous=null;
        values.forEach((value,j)=>{
          if(!Number.isFinite(value)){previous=null;return;}
          const time=channel.times[j],x=left+(time-result.start)/sharedDuration*plotWidth,y=center-value/shared[channel.channel]*dy*.39;
          const interrupted=previous!==null&&(time-previous>1.5/fs||gaps.some(g=>g.start>=previous&&g.start<time));
          if(previous===null||interrupted)ctx.moveTo(x,y);else ctx.lineTo(x,y);
          previous=time;
        });ctx.stroke();
      }
    });
  }));
}
