function exportModel(){if(!state.model?.id){toast('Train and evaluate a model before exporting.','warning');return}openModal('Export model for review',`<p class="small-copy">Export this evaluated model as a versioned package with its preprocessing requirements, channels, units and thresholds. Export does not install it into Focus Room.</p><pre class="json-result">${esc(JSON.stringify({id:state.model.id,split:state.model.split,test:state.model.test},null,2))}</pre>`,[{text:'Cancel',action:closeModal},{text:'Approve package export',primary:true,action:async()=>{const result=await action('export_model',{model_id:state.model.id,approved:true});openModal('Model package saved',`<p class="small-copy">The versioned package is saved locally. Production promotion requires a separate, explicit code review.</p><pre class="json-result">${esc(JSON.stringify(result,null,2))}</pre>`,[{text:'Done',action:closeModal}])}}])}
function renderSync(){const sync=state.server?.sync||{};if(document.activeElement!==$('sync-repository'))$('sync-repository').value=sync.repository||'';if(document.activeElement!==$('sync-enabled'))$('sync-enabled').checked=!!sync.enabled;const jobs=sync.jobs||[];const target=$('sync-status-list');target.className='results-content';target.innerHTML=`<p class="small-copy">${sync.configured?`${esc(sync.repository)} · ${sync.enabled?'automatic sync enabled':'automatic sync disabled'}`:'No repository configured.'}</p>${sync.error?`<div class="result-error">${esc(sync.error)}</div>`:''}${jobs.length?jobs.map(job=>`<div class="sync-job"><div>${esc(state.sessions.find(s=>s.id===job.session_id)?.title||job.session_id||'Session')}<small>Revision ${job.revision??'—'}${job.error?' · '+esc(job.error):''}</small></div><span class="state ${esc(job.state)}">${esc((job.state||'saved_locally').replaceAll('_',' '))}</span></div>`).join(''):'<p class="small-copy">Completed sessions appear here when they are queued.</p>'}<details style="margin-top:16px"><summary>Full synchronization status</summary><pre class="json-result">${esc(JSON.stringify(sync,null,2))}</pre></details>`;const hasFailed=jobs.some(j=>j.state==='failed');$('sync-nav-dot').className=hasFailed?'status-dot':'';$('sync-nav-dot').style.background=hasFailed?'var(--red)':''}
async function scanDevices(){const result=await action('scan');state.scanned=Array.isArray(result)?result:(result.devices||result.ports||[]);$('device-list').innerHTML=state.scanned.length?state.scanned.map((d,i)=>`<div class="device-row"><label><input type="checkbox" data-device-index="${i}" ${i<2?'checked':''}><span><strong>${esc(d.name||d.description||d.path||d.device||d.address||'Zone device')}</strong><small>${esc(d.address||d.path||d.device||d.port||'')} · ${esc(d.manufacturer||d.serial_number||'')}</small></span></label><select data-device-ear="${i}" aria-label="Ear assignment"><option value="left" ${i===0?'selected':''}>Left</option><option value="right" ${i!==0?'selected':''}>Right</option></select></div>`).join(''):'<p class="small-copy" style="padding-bottom:15px">No compatible Bluetooth devices found. Make Zone earbuds discoverable, then scan again.</p>'}
async function connectDevices(){const chosen=$$('[data-device-index]:checked');if(!chosen.length){toast('Scan and select at least one device.','warning');return}const request={};for(const input of chosen){const index=Number(input.dataset.deviceIndex),d=state.scanned[index],ear=document.querySelector(`[data-device-ear="${index}"]`).value;if(request[`${ear}_address`]){toast('Choose only one device for each ear.','warning');return}request[`${ear}_address`]=d.address||d.path||d.device||d.port;}await action('connect',{request},'Connection requested. Real samples confirm streaming.');await poll()}
function showAcquisition(){openModal('Acquisition & timing',`<p class="small-copy">Signal-only analysis uses recorded sensor samples. Hardware diagnostic settings must be verified from firmware; a noise score is never shown as impedance.</p><pre class="json-result">${esc(JSON.stringify({timing:state.session?.timing||'Host receive-time estimates. Inspect acquisition metadata for sample configuration and clock limitations.',units:nativeUnits(),acquisition:state.session?.acquisition||state.server?.hardware,upstream_processing:state.session?.upstream_processing||'See verified hardware acquisition metadata.'},null,2))}</pre>`,[{text:'Close',action:closeModal}])}
const featureNames=['amplitude','variance','flatline','abrupt_changes','drift','spectral_power','line_noise'];$('feature-grid').innerHTML='<p class="small-copy" style="grid-column:1/-1">Transparent baseline features</p>'+featureNames.map(name=>`<label><input type="checkbox" data-feature="${name}" checked>${name.replaceAll('_',' ')}</label>`).join('');
bind('hardware-toggle',()=>{$('connection-panel').hidden=!$('connection-panel').hidden});bind('connection-close',()=>{$('connection-panel').hidden=true});bind('empty-connect',()=>{$('connection-panel').hidden=false;return scanDevices()});bind('scan-devices',scanDevices);bind('connect-devices',connectDevices);bind('disconnect-devices',async()=>{await action('disconnect',{},'Devices disconnected. Recording state is separate.');await poll()});bind('simulate',async()=>{await action('simulate',{},'Simulated stream started. This is not hardware validation.');state.live=true;state.paused=false;state.sessionId=null;state.session=null;state.annotations=[];state.events=[];state.processed=null;state.samples={};renderAnnotations();$('connection-panel').hidden=true;await poll()});bind('record-toggle',toggleRecording);bind('record-details',()=>recordDetails(false));bind('section-toggle',toggleSection);bind('new-label',()=>labelEditor());bind('manage-labels',manageLabels);bind('clear-label',()=>selectLabel(null));bind('add-marker',markerDialog);bind('mark-previous',markPrevious);bind('review-selection',()=>editAnnotation());bind('add-range',()=>editAnnotation());bind('undo-annotation',undo);bind('shortcut-help',shortcutGuide);bind('viewer-pause',togglePause);bind('return-live',returnLive);bind('pan-left',()=>pan(-1));bind('pan-right',()=>pan(1));bind('jump-next',jumpNext);bind('raw-mode',()=>{state.paired=false;$('processed-panel').hidden=true;$('raw-mode').classList.add('selected');$('paired-mode').classList.remove('selected');drawAll()});bind('paired-mode',()=>{state.paired=true;$('processed-panel').hidden=false;$('paired-mode').classList.add('selected');$('raw-mode').classList.remove('selected');drawAll()});bind('open-processing',()=>showView('processing'));bind('signal-method',showAcquisition);bind('refresh-library',refreshLibrary);bind('import-session',importSession);bind('add-protocol-step',()=>{protocolSteps.push({label_id:state.labels[0]?.id,duration:30});renderProtocolSteps()});bind('protocol-save',()=>action('protocol',protocolPayload('save'),'Experiment saved.'));bind('protocol-start',async()=>{await action('protocol',protocolPayload('start'),'Experiment started. Instructions are scheduled, not confirmed observations.');await poll()});bind('protocol-advance',async()=>{await action('protocol',{command:'advance'});await poll()});bind('protocol-stop',async()=>{await action('protocol',{command:'stop'},'Experiment stopped. Recording continues.');await poll()});bind('train-model',trainModel);bind('extract-features',extractFeatures);bind('run-compare',compareConditions);bind('run-processing',processSession);bind('generate-candidate',generateCandidate);bind('import-plugin',importPlugin);bind('export-model',exportModel);bind('sync-retry',async()=>{await action('sync_retry',{},'Pending uploads queued for retry.');await poll()});bind('save-sync',async()=>{const result=await action('sync_config',{repository:$('sync-repository').value.trim(),enabled:$('sync-enabled').checked});resultsBox('sync-config-result',result);await poll();toast('Synchronization configuration saved.');});
$('label-search').addEventListener('input',()=>renderLabels());$('time-window').addEventListener('change',async()=>{state.window=Number($('time-window').value);state.end=Math.max(state.window,state.end);if(state.sessionId&&(!state.live||state.paused))await loadSamples();drawAll()});$('amplitude-mode').addEventListener('change',drawAll);$('amplitude-value').addEventListener('input',drawAll);['session-search','session-date','session-label-filter','session-review-filter'].forEach(id=>$(id).addEventListener(id==='session-search'?'input':'change',renderLibrary));$('label-countdown').addEventListener('change',()=>action('settings',{settings:{countdown:Number($('label-countdown').value)}}));$('label-scope').addEventListener('change',()=>action('select_label',{label_id:state.selectedLabel,scope:scopeValue()}));
// Focus Room comparison uses the verified production reference supplied by the backend.
const focusButton=document.createElement('button');focusButton.id='run-focus-compare';focusButton.className='button';focusButton.textContent='Run current Focus Room reference';$('run-compare').parentElement.append(focusButton);bind('run-focus-compare',()=>runResult('comparison-results','run-focus-compare',async()=>{const example=await comparisonExample($('compare-session-a').value,$('compare-label-a').value);const result=await action('focus_compare',{...example,pipeline:normalizePipeline()});resultsBox('comparison-results',result)}));
const restoreButton=document.createElement('button');restoreButton.id='sync-restore';restoreButton.className='button';restoreButton.textContent='Restore a verified remote session';$('sync-status-list').parentElement.append(restoreButton);bind('sync-restore',()=>openModal('Restore remote session',`<label class="field-label">Session ID</label><input id="restore-id" placeholder="32-character session identifier"><label class="field-label">Revision</label><input id="restore-revision" type="number" min="0" value="1"><p class="small-copy">The complete portable archive is downloaded and verified before import. Conflicting local revisions are preserved.</p>`,[{text:'Cancel',action:closeModal},{text:'Download & verify',primary:true,action:async()=>{const result=await action('sync_restore',{session_id:$('restore-id').value.trim(),revision:Number($('restore-revision').value)});openModal('Remote archive verified',`<pre class="json-result">${esc(JSON.stringify(result,null,2))}</pre>`,[{text:'Close',action:closeModal},{text:'Import verified archive',primary:true,action:async()=>{const session=await api('/api/import',{path:result.path||result.archive});closeModal();await refreshLibrary();await openSession(session.id)}}])}}]));
// Setup runs after every DOM control exists. Each poll is awaited to avoid overlap.
await poll();$('label-countdown').value=String(state.settings.countdown||0);await refreshLibrary();setInterval(poll,600);
